import type { Request, Response } from "express";
import { userService } from "./user.service";
import sendResponse from "../../utility/serverResponse";


const createUser = async (req: Request, res: Response) => {

     try {


          const { name, email, password } = req.body;
          if (!name || !email || !password) {
               return res.status(400).json({
                    success: false,
                    message: " Name, email, and password are required!"
               });
          }

          const result = await userService.insetUserIntoDB(req.body)

          res.status(201).json({
               success: true,
               message: "User Created successfully!",
               data: result.rows[0]
          });

     } catch (error: any) {
          res.status(500).json({
               success: false,
               message: error.message,
               error: error
          });
     }
}

const getAllUser = async (req: Request, res: Response) => {
     try {
          const result = await userService.getAlluserFromDB()
          if (result.rows.length === 0) {

               return res.status(404).json({
                    success: false,
                    message: "User Not found!",
                    data: {},
               });

          }
          // console.log(result);
          return res.status(200).json({
               success: true,
               message: 'successfully data retrive',
               data: result.rows
          })
     } catch (error: any) {
          res.status(500).json({
               success: false,
               message: error.message,
               error: error
          })


     }
}

const getSingleUser = async (req: Request, res: Response) => {
     try {
          const { id } = req.params
          if (!id) {
               return res.status(400).json({
                    success: false,
                    message: "ID is must be required!"
               });
          }
          const result = await userService.getSingleUserFromDB(id as string)
          if (result.rows.length === 0) {

               return res.status(404).json({
                    success: false,
                    message: "User Not found!",
                    data: {},
               });

          }

          sendResponse(res,
               {
                    statusCode: 200,
                    success: true,
                    message: "Users fetched successfully!",
                    data: result.rows[0],
               })


     } catch (error: any) {
          sendResponse(res,
               {
                    statusCode: 500,
                    success: false,
                    message: error.message,
                    error: error,
               }

          )



     }
}

const updateUser = async (req: Request, res: Response) => {
     try {
          const { id } = req.params
          if (!id) {
               return res.status(400).json({
                    success: false,
                    message: "ID is must be required!"
               });
          }

          const result = await userService.updateUserFromDB(id as string, req.body)
          if (result.rows.length === 0) {

               return res.status(404).json({
                    success: false,
                    message: "User Not found!",
                    data: {},
               });

          }
          return res.status(200).json({
               success: true,
               message: 'successfully data retrive',
               data: result.rows[0]
          })
     } catch (error: any) {
          return res.status(500).json({
               success: false,
               message: error.message,
               error: error
          })


     }
}

const deleteUser = async (req: Request, res: Response) => {
     try {
          const { id } = req.params
          if (!id) {
               return res.status(400).json({
                    success: false,
                    message: "ID is must be required!"
               });
          }
          const result = await userService.deleteUserFormDB(id as string)
          if (result.rowCount === 0) {
               return res.status(404).json({
                    success: false,
                    message: 'user not founds',

               })
          }
          return res.status(200).json({
               success: true,
               message: 'successfully data deleted',
               data: result.rows[0]
          })
     } catch (error: any) {
          return res.status(500).json({
               success: false,
               message: error.message,
               error: error
          })


     }
}

export const userController = {

     createUser,
     getAllUser,
     getSingleUser,
     updateUser,
     deleteUser

}